#[test]
fn nested_retirement_projection_obeys_original_source_depth_and_json_oracle(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/♻️retirement.json")).unwrap();let value=|name:&str|ValueError::new(ValueRefusalKind::Canceled,fixture[name].as_str().unwrap().to_owned());let inner=semio_framework_value::OriginalRetirementFailure::from_causes(Some(value("innerPrimary")),Some(value("innerWork")),Some(value("innerReceipt")),Some(value("innerAllocation").into())).with_retained_progress(RetainedCloneProgress{copied_bytes:7,..Default::default()});let(admitted,actual,_)=driver::funded(&mut driver::bank(),semio_framework_value::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64},1<<20,|effect|semio_framework_value::OriginalFailureStorage::admit(effect));let(storage,birth)=admitted.result.unwrap();assert_eq!(actual,Some(semio_framework_value::OriginalFailureStorage::birth_bytes()));assert_eq!(birth.retained_capacity_bytes,actual.unwrap());let original=storage.attach_owned_parts(inner,None,Some(value("outerWork")),None,None).with_retained_progress(RetainedCloneProgress{copied_bytes:11,..Default::default()});
 let nodes=fixture["nodes"].as_u64().unwrap()as usize;
 for row in fixture["sourceDepthCases"].as_array().unwrap(){let depth=row["depth"].as_u64().unwrap()as usize;let accepted=row["accepted"].as_bool().unwrap();assert_eq!(accepted,depth>=nodes);source::with_source_authorities(65536,depth,|control|{assert_eq!(control.check_additional_depth(nodes).is_ok(),accepted);if !accepted{assert_eq!(semio_framework_io_failure_owner::retirement_value(&original,control).unwrap_err().kind,ValueRefusalKind::DepthLimit)}});}
 for row in fixture["enclosingDepthCases"].as_array().unwrap(){let depth=row["depth"].as_u64().unwrap()as usize;let accepted=row["accepted"].as_bool().unwrap();assert_eq!(accepted,depth>=nodes+1);source::with_source_authorities(65536,depth,|control|control.scoped_depth(usize::MAX,|control|{assert_eq!(control.check_additional_depth(nodes).is_ok(),accepted);if !accepted{assert_eq!(semio_framework_io_failure_owner::retirement_value(&original,control).unwrap_err().kind,ValueRefusalKind::DepthLimit)}Ok::<(),ValueError>(())})).unwrap();}
 let mut observer=|_|true;let mut control=semio_framework_value::NativeEncodeControl::new(65536,&mut observer);let projected=semio_framework_io_failure_owner::retirement_value(&original,&mut control).unwrap();let json=serde_json::to_value(&projected).unwrap();assert_eq!(json["progressOverride"]["copiedBytes"],11);assert_eq!(json["child"]["progressOverride"]["copiedBytes"],7);assert_eq!(json["workRefusal"]["message"],fixture["outerWork"]);assert_eq!(json["child"]["primary"]["message"],fixture["innerPrimary"]);assert_eq!(json["child"]["workRefusal"]["message"],fixture["innerWork"]);assert_eq!(json["child"]["receiptRefusal"]["message"],fixture["innerReceipt"]);assert_eq!(json["child"]["allocationRefusal"]["message"],fixture["innerAllocation"]);drop(control);let grant=semio_framework_value::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:4096};close(projected,grant,4096);close(original,grant,4096);
}

#[test]
fn receiving_wire_retains_each_allocation_cause_and_physical_progress(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🛂️receiving-allocation.json")).unwrap();let names=fixture["channels"].as_array().unwrap();let owned=|i:usize|ValueError::new(ValueRefusalKind::Canceled,names[i].as_str().unwrap().to_owned());let grant=semio_framework_value::RetainedCloneGrant{maximum_items:100000,maximum_copy_bytes:1048576,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:4096};for actual in fixture["actualCapacityCases"].as_array().unwrap(){let mut receiving=OriginalReceivingPrimary::from_decoded_fields(None,None,None,Some(ValueError::new(ValueRefusalKind::WorkLimit,fixture["workRefusal"].as_str().unwrap().to_owned())),Some(ValueError::new(ValueRefusalKind::WorkLimit,fixture["workOverrun"].as_str().unwrap().to_owned())),Some(semio_framework_value::OriginalRetirementFailure::from_causes(Some(ValueError::new(ValueRefusalKind::Canceled,"nested retirement".to_owned())),None,None,Some(ValueError::new(ValueRefusalKind::Canceled,"nested allocation".to_owned()).into()))),Some(Default::default()),Some(semio_framework_value_native_owned::native_decoding::NativeDecodeAllocationOutcome{request:None,admitted:true,quote_refusal:Some(owned(3).into()),primary:Some(owned(0)),extent_refusal:Some(owned(1)),settlement_refusal:Some(owned(2).into()),actual:Some(0)}),Some(ValueError::new(ValueRefusalKind::Canceled,fixture["receipt"].as_str().unwrap().to_owned())),Some(ValueError::new(ValueRefusalKind::Canceled,fixture["receiptCompletion"].as_str().unwrap().to_owned())),Default::default());let allocation=receiving.allocation_failure.as_mut().unwrap();allocation.primary=Some(owned(0));allocation.admission=Some(owned(1));allocation.forwarded_admission=Some(owned(2).into());allocation.scoped_admission=Some(owned(3).into());allocation.forwarded_quote=Some(owned(4).into());allocation.scoped_quote=Some(owned(5).into());allocation.forwarded_post=Some(owned(6).into());allocation.scoped_post=Some(owned(7).into());allocation.forwarded_cancel=Some(owned(8).into());allocation.scoped_cancel=Some(owned(9).into());allocation.receipt=Some(owned(10));allocation.extent=Some(owned(11));allocation.progress.prior_admitted_bytes=(!actual.is_null()).then(||fixture["priorAdmittedBytes"].as_u64().unwrap()as usize);allocation.progress.requested_bytes=(!actual.is_null()).then(||fixture["requestedBytes"].as_u64().unwrap()as usize);allocation.progress.maximum_bytes=(!actual.is_null()).then(||fixture["maximumBytes"].as_u64().unwrap()as usize);allocation.progress.admitted_bytes=fixture["admittedBytes"].as_u64().unwrap()as usize;allocation.progress.actual_capacity_bytes=actual.as_u64().map(|v|v as usize);let original_overrun=receiving.work_overrun.as_ref().unwrap().message.as_ptr();let original_completion=receiving.receipt_completion().unwrap().message.as_ptr();let original=NativeSnapshotFailure::from(receiving);assert_eq!(original.receiving_primary().unwrap().work_overrun.as_ref().unwrap().message.as_ptr(),original_overrun);assert_eq!(original.receiving_primary().unwrap().receipt_completion().unwrap().message.as_ptr(),original_completion);assert_eq!(original.receipt_refusal().unwrap().message.as_ref(),fixture["receipt"].as_str().unwrap());let mut observe=|_|true;let mut encoder=semio_framework_value::NativeEncodeControl::new(grant.maximum_capacity_bytes,&mut observe);let wire=original.to_value_controlled(&mut encoder).unwrap();drop(encoder);let json=serde_json::to_value(&wire).unwrap();assert_eq!(json["cause"]["workRefusal"]["message"],fixture["workRefusal"]);assert_eq!(json["cause"]["workOverrun"]["message"],fixture["workOverrun"]);assert_eq!(json["cause"]["receiptCompletion"]["message"],fixture["receiptCompletion"]);assert_eq!(json["cause"]["retirementFailure"]["primary"]["message"],"nested retirement");assert_eq!(json["cause"]["retirementFailure"]["allocationRefusal"]["message"],"nested allocation");for name in names{let name=name.as_str().unwrap();assert_eq!(json["cause"]["allocationFailure"][name]["message"],name)}assert_eq!(json["cause"]["allocationFailure"]["progress"]["actualCapacityBytes"],*actual);let decoded=receive_wire(wire);assert_eq!(decoded.receiving_primary().unwrap().work_refusal.as_ref().unwrap().message,fixture["workRefusal"].as_str().unwrap());assert_eq!(decoded.receiving_primary().unwrap().work_overrun.as_ref().unwrap().message,fixture["workOverrun"].as_str().unwrap());assert_eq!(decoded.receiving_primary().unwrap().receipt_completion().unwrap().message,fixture["receiptCompletion"].as_str().unwrap());assert_eq!(decoded,original);close(decoded,grant,100000);close(original,grant,100000);}}

#[test]
fn incomplete_allocation_request_refuses_encoding_without_moving_its_owner(){let mut receiving=OriginalReceivingPrimary::from_fields(None,None,None,None,None,None,Some(Default::default()),None,None,Default::default());receiving.allocation_failure.as_mut().unwrap().progress.requested_bytes=Some(73);let failure=NativeSnapshotFailure::from(receiving);let mut observer=|_|true;let mut encoder=semio_framework_value::NativeEncodeControl::new(65536,&mut observer);assert!(failure.to_value_controlled(&mut encoder).is_err());assert_eq!(failure.receiving_primary().unwrap().allocation_failure.as_ref().unwrap().progress.requested_bytes,Some(73));drop(encoder);close(failure,semio_framework_value::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:128},4096);}

#[test]fn encode_effect_failure_retains_every_original_cause_and_projects_wire(){use semio_framework_value::native_encoding::{NativeAllocationRequest,NativeEncodeAllocationOutcome,NativeEncodeEffectFailure};let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🎟️encode-effect.json")).unwrap();let source=&fixture["encodeEffect"];let error=|v:&serde_json::Value|Some(ValueError::new(ValueRefusalKind::Canceled,v["message"].as_str().unwrap().to_owned()));let a=&source["allocation"];let request=&a["request"];let effect=NativeEncodeEffectFailure{primary:error(&source["primary"]),context:error(&source["context"]),invariant:error(&source["invariant"]),physical_invariant:error(&source["physicalInvariant"]),capacity_invariant:error(&source["capacityInvariant"]),marker_failure:error(&source["markerFailure"]),work:error(&source["work"]),work_overrun:error(&source["workOverrun"]),local:error(&source["local"]),physical:error(&source["physical"]),physical_receipt:None,allocation:Some(NativeEncodeAllocationOutcome{request:Some(NativeAllocationRequest{bytes:request["bytes"].as_u64().unwrap()as usize,owned_bytes:request["ownedBytes"].as_u64().unwrap()as usize,next_owned_bytes:request["nextOwnedBytes"].as_u64().unwrap()as usize,maximum_bytes:request["maximumBytes"].as_u64().unwrap()as usize}),admitted:a["admitted"].as_bool().unwrap(),primary:error(&a["primary"]),forwarded_quote:error(&a["forwardedQuote"]).map(Into::into),scoped_quote:error(&a["scopedQuote"]).map(Into::into),extent_refusal:error(&a["extentRefusal"]),forwarded_refusal:error(&a["forwardedRefusal"]).map(Into::into),scoped_refusal:error(&a["scopedRefusal"]).map(Into::into),actual:a["actual"].as_u64().map(|v|v as usize)})};let pointers=[effect.primary.as_ref().unwrap().message.as_ptr(),effect.context.as_ref().unwrap().message.as_ptr(),effect.invariant.as_ref().unwrap().message.as_ptr(),effect.physical_invariant.as_ref().unwrap().message.as_ptr(),effect.capacity_invariant.as_ref().unwrap().message.as_ptr(),effect.marker_failure.as_ref().unwrap().message.as_ptr(),effect.work.as_ref().unwrap().message.as_ptr(),effect.work_overrun.as_ref().unwrap().message.as_ptr(),effect.local.as_ref().unwrap().message.as_ptr(),effect.physical.as_ref().unwrap().message.as_ptr(),effect.allocation.as_ref().unwrap().scoped_refusal.as_ref().unwrap().owned().unwrap().message.as_ptr()];let failure=NativeSnapshotFailure::from_encode_effect(effect,RetainedCloneProgress::default());let effect=failure.encode_effect().unwrap();assert_eq!([effect.primary.as_ref().unwrap().message.as_ptr(),effect.context.as_ref().unwrap().message.as_ptr(),effect.invariant.as_ref().unwrap().message.as_ptr(),effect.physical_invariant.as_ref().unwrap().message.as_ptr(),effect.capacity_invariant.as_ref().unwrap().message.as_ptr(),effect.marker_failure.as_ref().unwrap().message.as_ptr(),effect.work.as_ref().unwrap().message.as_ptr(),effect.work_overrun.as_ref().unwrap().message.as_ptr(),effect.local.as_ref().unwrap().message.as_ptr(),effect.physical.as_ref().unwrap().message.as_ptr(),effect.allocation.as_ref().unwrap().scoped_refusal.as_ref().unwrap().owned().unwrap().message.as_ptr()],pointers);let mut observe=|_|true;let mut native=semio_framework_value::NativeEncodeControl::new(1<<20,&mut observe);let wire=failure.to_value_controlled(&mut native).unwrap();assert_eq!(serde_json::to_value(&wire).unwrap(),fixture);drop(native);let grant=semio_framework_value::RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:4096};let decoded=receive_wire(wire);assert_eq!(decoded,failure);close(decoded,grant,100000);close(failure,grant,100000);}

#[test]fn retained_allocation_refusal_stays_with_its_original_vault_during_wire_projection(){use semio_framework_value::RetainedCloneGrant;use semio_framework_value_control_contract::{NativeAllocationRefusal,NativeAllocationRefusalVault};let mut vault=NativeAllocationRefusalVault::default();let original=ValueError::new(ValueRefusalKind::Canceled,"original allocation owner".to_owned());let pointer=original.message.as_ptr();let handle=vault.retain(original).unwrap();let refusal=NativeAllocationRefusal::Retained(handle);let mut callback=|_|true;let mut control=semio_framework_value::NativeEncodeControl::new(4096,&mut callback);let error=semio_framework_io_failure_owner::optional_refusal(Some(&refusal),&mut control).unwrap_err();assert_eq!(error.kind,ValueRefusalKind::UnsupportedOwner);drop(control);let NativeAllocationRefusal::Retained(handle)=refusal else{unreachable!()};let original=vault.take(handle).unwrap();assert_eq!(original.message.as_ptr(),pointer);let grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64};close(error,grant,1024);close(original,grant,1024);}

#[test]fn owned_allocation_refusal_projects_wire_without_moving_original(){use semio_framework_value::RetainedCloneGrant;use semio_framework_value_control_contract::NativeAllocationRefusal;let original=ValueError::new(ValueRefusalKind::Canceled,"owned allocation refusal".to_owned());let pointer=original.message.as_ptr();let refusal=NativeAllocationRefusal::Owned(original);let mut callback=|_|true;let mut control=semio_framework_value::NativeEncodeControl::new(4096,&mut callback);let wire=semio_framework_io_failure_owner::optional_refusal(Some(&refusal),&mut control).unwrap();drop(control);let NativeAllocationRefusal::Owned(original)=refusal else{unreachable!()};assert_eq!(original.message.as_ptr(),pointer);let grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64};close(wire,grant,1024);close(original,grant,1024);}

#[test]
fn staged_recursive_retirement_preserves_each_original_cause(){
 let wire:semio_framework_value::DslValue=serde_json::from_str(include_str!("🧫️fixtures/♻️recursive-retirement.json")).unwrap();
 let failure=receive_wire(wire);let outer=failure.retirement_failure().unwrap();let inner=outer.child().unwrap();
 for(node,prefix)in[(outer,"outer"),(inner,"inner")]{assert_eq!(node.primary().unwrap().message,format!("{prefix} primary"));assert_eq!(node.work_refusal().unwrap().message,format!("{prefix} work"));assert_eq!(node.receipt_refusal().unwrap().message,format!("{prefix} receipt"));assert_eq!(node.allocation_refusal().unwrap().owned().unwrap().message,format!("{prefix} allocation"));assert_eq!(node.retained_progress().copied_bytes,3);}
 assert!(inner.child().is_none());let grant=semio_framework_value::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:1048576,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:4096};close(failure,grant,1000000);
}
/// 🪢️ Native receiving keeps its actual retirement owner through the closed snapshot codec.
#[test]
fn receiving_retirement_is_not_erased_by_wire_or_equality(){let primary=semio_framework_value::OriginalRetirementFailure::from_causes(Some(ValueError::literal(ValueRefusalKind::InvalidValue,"original inner retirement 源")),Some(ValueError::literal(ValueRefusalKind::WorkLimit,"independent inner work")),Some(ValueError::literal(ValueRefusalKind::Canceled,"independent inner receipt")),None);let mut receiving=OriginalReceivingPrimary::from(primary);receiving.work_refusal=Some(ValueError::literal(ValueRefusalKind::WorkLimit,"outer receiving work"));let original=NativeSnapshotFailure::from(receiving);let grant=semio_framework_value::RetainedCloneGrant{maximum_items:65536,maximum_copy_bytes:1048576,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:4096};let mut observe=|_|true;let mut native=semio_framework_value::NativeEncodeControl::new(1048576,&mut observe);let wire=original.to_value_controlled(&mut native).unwrap();drop(native);let json=serde_json::to_value(&wire).unwrap();assert_eq!(json["cause"]["retirementFailure"]["primary"]["message"],"original inner retirement 源");assert_eq!(json["cause"]["workRefusal"]["message"],"outer receiving work");let decoded=receive_wire(wire.clone());assert_eq!(decoded,original);assert!(decoded.receiving_primary().unwrap().retirement_failure.is_some());close(decoded,grant,100000);close(original,grant,100000);close(wire,grant,100000);}

#[test]
fn encoding_physical_receipt_keeps_the_complete_original_receiving_owner(){
 use semio_framework_value::native_encoding::NativeEncodeEffectFailure;
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🎟️physical-receipt.json")).unwrap();let source=&fixture["encodeEffect"]["physicalReceipt"];
 let error=|key:&str,kind:ValueRefusalKind|{let value=&source[key];let p=&value["retainedProgress"];Some(ValueError::new(kind,value["message"].as_str().unwrap().to_owned()).with_retained_progress(RetainedCloneProgress{copied_items:p["copiedItems"].as_u64().unwrap()as usize,copied_bytes:p["copiedBytes"].as_u64().unwrap()as usize,retained_capacity_bytes:p["retainedCapacityBytes"].as_u64().unwrap()as usize,released_bytes:p["releasedBytes"].as_u64().unwrap()as usize}))};
 let receipt=OriginalReceivingPrimary::from_decoded_fields(None,None,None,error("workRefusal",ValueRefusalKind::WorkLimit),error("workOverrun",ValueRefusalKind::WorkLimit),None,None,None,error("receiptRefusal",ValueRefusalKind::Canceled),error("receiptCompletion",ValueRefusalKind::Canceled),Default::default());let pointer=receipt.receipt_completion().unwrap().message.as_ptr();let effect=NativeEncodeEffectFailure{physical_receipt:Some(receipt),..Default::default()};let failure=NativeSnapshotFailure::from_encode_effect(effect,RetainedCloneProgress::default());assert_eq!(failure.message(),"original work refusal");assert_eq!(failure.encode_effect().unwrap().physical_receipt.as_ref().unwrap().receipt_completion().unwrap().message.as_ptr(),pointer);
 let mut observer=|_|true;let mut native=semio_framework_value::NativeEncodeControl::new(1<<20,&mut observer);let wire=failure.to_value_controlled(&mut native).unwrap();assert_eq!(serde_json::to_value(&wire).unwrap(),fixture);drop(native);let grant=semio_framework_value::RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:4096};let decoded=receive_wire(wire);assert_eq!(decoded,failure);close(decoded,grant,100000);close(failure,grant,100000);
}
